// Vectors derived from NextShell 1.x connection-export-crypto.ts and finalshell/decrypt-password.ts only.
// No third-party SSH-client code is used. Triple DES with K,K,K is exactly single DES.
import {scryptSync,createCipheriv,createHash} from 'node:crypto';import {writeFileSync} from 'node:fs';
const salt=Buffer.from(Array.from({length:32},(_,i)=>i)),iv=Buffer.from(Array.from({length:12},(_,i)=>100+i));
const plain=JSON.stringify({format:'nextshell-connections',version:1,exportedAt:'2026-06-15T00:00:00.000Z',connections:[{name:'prod-a',host:'10.0.0.1',port:22,username:'root',authType:'password',password:'中文-secret',groupPath:'/server/prod',tags:[],favorite:false,terminalEncoding:'utf-8',backspaceMode:'ascii-backspace',deleteMode:'vt220-delete',monitorSession:false}]},null,2),password='导出口令';
const cipher=createCipheriv('aes-256-gcm',scryptSync(password,salt,32,{N:16384,r:8,p:1}),iv,{authTagLength:16});cipher.setAAD(Buffer.from('nextshell-connection-export'));const ct=Buffer.concat([cipher.update(plain),cipher.final()]);
const exportVector={password,plain,salt:salt.toString('base64'),iv:iv.toString('base64'),encrypted:'b64##'+Buffer.concat([salt,iv,cipher.getAuthTag(),ct]).toString('base64')};
class JR{constructor(seed){this.seed=(BigInt(seed)^25214903917n)&((1n<<48n)-1n)}next(bits){this.seed=(this.seed*25214903917n+11n)&((1n<<48n)-1n);return Number(this.seed>>BigInt(48-bits))}nextInt(bound){if((bound&-bound)===bound)return Math.floor(bound*this.next(31)/0x80000000);for(;;){const bits=this.next(31),v=bits%bound;if(bits-v+bound-1>=0)return v}}nextLong(){return BigInt.asIntN(64,(BigInt(this.next(32)|0)<<32n)+BigInt(this.next(32)|0))}}
function key(head,signed){const b=i=>signed&&head[i]>127?head[i]-256:head[i];const divisor=new JR(b(5)).nextInt(127);if(!divisor)throw Error('divisor zero');const r=new JR(3680984568597093857n/BigInt(divisor));for(let i=0;i<b(0);i++)r.nextLong();const r2=new JR(r.nextLong()),values=[BigInt(b(4)),r2.nextLong(),BigInt(b(7)),BigInt(b(3)),r2.nextLong(),BigInt(b(1)),r.nextLong(),BigInt(b(2))];const material=Buffer.alloc(64);values.forEach((n,i)=>material.writeBigInt64BE(n,i*8));return createHash('md5').update(material).digest().subarray(0,8)}
const finals=[];for(const signed of [false,true]){const head=Buffer.from([130,240,3,250,19,200,90,210]),k=key(head,signed),plaintext='FinalShell 中文 密码';const c=createCipheriv('des-ede3',Buffer.concat([k,k,k]),null);const ct=Buffer.concat([c.update(plaintext),c.final()]);finals.push({signed,keyHex:k.toString('hex'),head:head.toString('base64'),plaintext,encoded:Buffer.concat([head,ct]).toString('base64')})}
writeFileSync(new URL('./v1-vectors.json',import.meta.url),JSON.stringify({exportVector,finals},null,2)+'\n');
